import{_ as t,o,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph User + Dev Monthly Meetup June","description":"","frontmatter":{"title":"Ceph User + Dev Monthly Meetup June","date":"2025-06-18T00:00:00.000Z","updated":"2025-06-18T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","高可用性","可扩展性","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_User_+_Dev_Monthly_Meetup_June.md","filePath":"posts/2025/Ceph_User_+_Dev_Monthly_Meetup_June.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Ceph_User_+_Dev_Monthly_Meetup_June.md"};function l(a,e,i,g,p,u){return o(),r("div",null,[...e[0]||(e[0]=[s('<h3 id="ceph-用户开发会议纪要" tabindex="-1">Ceph 用户开发会议纪要 <a class="header-anchor" href="#ceph-用户开发会议纪要" aria-label="Permalink to &quot;Ceph 用户开发会议纪要&quot;">​</a></h3><p><strong>日期</strong>：2023年XX月XX日<br><strong>主题</strong>：PG Autoscaler 优化与 CephFS 反馈讨论</p><h4 id="_1-会议概览" tabindex="-1"><strong>1. 会议概览</strong> <a class="header-anchor" href="#_1-会议概览" aria-label="Permalink to &quot;**1. 会议概览**&quot;">​</a></h4><p>本次会议主要围绕以下议题展开：</p><ul><li><strong>PG Autoscaler 的用户反馈与改进方向</strong></li><li><strong>CephFS 的灾难恢复（DR）文档优化与性能调优</strong></li></ul><h4 id="_2-主要讨论内容" tabindex="-1"><strong>2. 主要讨论内容</strong> <a class="header-anchor" href="#_2-主要讨论内容" aria-label="Permalink to &quot;**2. 主要讨论内容**&quot;">​</a></h4><h5 id="_2-1-pg-autoscaler-反馈与改进" tabindex="-1"><strong>2.1 PG Autoscaler 反馈与改进</strong> <a class="header-anchor" href="#_2-1-pg-autoscaler-反馈与改进" aria-label="Permalink to &quot;**2.1 PG Autoscaler 反馈与改进**&quot;">​</a></h5><p><strong>关键问题</strong>：</p><ul><li><strong>配置复杂性</strong>：用户反馈当前 PG Autoscaler 的配置参数难以理解，缺乏直观指导。</li><li><strong>默认 PG 数量不足</strong>： <ul><li>元数据池（如 RGW 的 <code>index pool</code> 和 CephFS 的 <code>metadata pool</code>）的默认 PG 数无法满足高性能需求。</li><li>现有启发式算法基于容量比例，但未考虑对象数量或 CPU 负载均衡。</li></ul></li><li><strong>稳定性问题</strong>：早期版本中 PG 数量动态调整可能导致集群不稳定。</li></ul><p><strong>改进建议</strong>：</p><ul><li><strong>文档增强</strong>：明确 <code>bias</code> 和 <code>bulk</code> 参数的计算逻辑。</li><li><strong>新功能提案</strong>：添加 <code>ceph pg-autoscaler explain</code> 命令，详细输出 PG 数量建议的决策过程；支持初始化时一次性优化 PG 数量后转为“建议模式”。</li><li><strong>启发式算法优化</strong>：对元数据池采用独立启发式；考虑提升默认 <code>target PGs per OSD</code> 至 200。</li></ul><p><strong>后续行动</strong>：</p><ul><li>在 RADOS 周会深入讨论 PG Autoscaler 启发式算法改进。</li><li>整理用户反馈并推进相关 PR。</li></ul><h5 id="_2-2-cephfs-灾难恢复与性能调优" tabindex="-1"><strong>2.2 CephFS 灾难恢复与性能调优</strong> <a class="header-anchor" href="#_2-2-cephfs-灾难恢复与性能调优" aria-label="Permalink to &quot;**2.2 CephFS 灾难恢复与性能调优**&quot;">​</a></h5><p><strong>关键问题</strong>：</p><ul><li><strong>DR 文档复杂性</strong>：当前文档步骤冗长且未明确风险操作。</li><li><strong>工具改进需求</strong>：缺乏进度指示，内存消耗未文档化。</li><li><strong>性能调优指南缺失</strong>：用户难以判断何时启用多 MDS、调整 <code>ephemeral pinning</code> 参数等。</li></ul><p><strong>改进方向</strong>：</p><ul><li><strong>DR 文档优化</strong>：添加流程图区分“安全”与“高风险”操作；补充日志备份恢复的实操步骤。</li><li><strong>自动化工具开发</strong>：开发集成工具自动诊断集群状态并推荐恢复步骤。</li><li><strong>性能调优指南</strong>：基于 <code>perf dump</code> 指标编写瓶颈分析流程；推动 Prometheus 集成关键实时指标。</li></ul><p><strong>新功能预告</strong>：</p><ul><li><strong>审计日志</strong>：记录所有 CephFS 管理命令，便于故障回溯。</li></ul><p><strong>后续行动</strong>：</p><ul><li>更新 DR 文档，明确风险操作与内存需求。</li><li>创建 CephFS 调优指南协作项目。</li></ul><h4 id="_3-决议与行动计划" tabindex="-1"><strong>3. 决议与行动计划</strong> <a class="header-anchor" href="#_3-决议与行动计划" aria-label="Permalink to &quot;**3. 决议与行动计划**&quot;">​</a></h4><p>| <strong>事项</strong> | <strong>负责人</strong> | <strong>时间节点</strong> |<br> ||-|--|<br> | PG Autoscaler 算法讨论 | Junior | 下次 RADOS 周会 |<br> | DR 文档更新 | Venky | 2023年XX月XX日 |<br> | CephFS 调优指南启动 | Dan/Laura | 2023年XX月（待定） |</p><h4 id="_4-其他备注" tabindex="-1"><strong>4. 其他备注</strong> <a class="header-anchor" href="#_4-其他备注" aria-label="Permalink to &quot;**4. 其他备注**&quot;">​</a></h4><ul><li><strong>PG Autoscaler 长期目标</strong>：平衡小集群与大集群的默认配置。</li><li><strong>灾难恢复工具增强</strong>：未来版本将支持进度条与内存预警。</li></ul><p><strong>下次会议</strong>：待定（可能延续未完成的 CephFS 多 MDS 调优话题）。</p><p><strong>会议记录人</strong>：AI 助手（基于讨论整理）</p>',28)])])}const _=t(n,[["render",l]]);export{c as __pageData,_ as default};
